/**
 * Bundled Bailey Hall geometry (generated by `npm run geometry`, editable JSON).
 */
import raw from '../data/geometry/bailey-hall.json';
import type { GeometryData } from './types';

export const BAILEY_HALL: GeometryData = raw as unknown as GeometryData;

/** Corridor barrier slots (label like "W2" -> link id). */
export function barrierSlots(geo: GeometryData): { id: string; label: string; x: number; y: number }[] {
  return geo.links
    .filter((l) => l.barrierSlot)
    .map((l) => ({
      id: l.id,
      label: (l.label ?? l.id).replace('Barrier slot ', ''),
      x: (l.pts[0][0] + l.pts[l.pts.length - 1][0]) / 2,
      y: (l.pts[0][1] + l.pts[l.pts.length - 1][1]) / 2,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

export function slotId(geo: GeometryData, label: string): string {
  const s = barrierSlots(geo).find((b) => b.label === label);
  if (!s) throw new Error(`unknown barrier slot ${label}`);
  return s.id;
}

/** Links that can be blocked in the "blocked exit" scenario (doors, stairs). */
export function blockableLinks(geo: GeometryData): { id: string; label: string }[] {
  return geo.links
    .filter((l) => (l.kind === 'door' || (l.kind === 'stair' && l.gate)) && !l.prohibited)
    .map((l) => ({ id: l.id, label: l.label ?? l.id }));
}
